<?php
namespace App\Http\Controllers\Api\Admin;
use App\Http\Controllers\Controller;use Illuminate\Http\JsonResponse;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;use Illuminate\Validation\Rule;
class MarketingControlController extends Controller{
private const R=['budgets'=>['table'=>'marketing_budgets','prefix'=>'BUD'],'governance'=>['table'=>'marketing_governance_records','prefix'=>'GOV'],'reports-audit'=>['table'=>'marketing_report_definitions','prefix'=>'RPT']];
public function index(Request$r,string$resource):JsonResponse{$this->permit($r,$resource,'view');if($resource==='attribution-analytics')return$this->attribution($r);$c=$this->cfg($resource);$r->validate(['per_page'=>['nullable','integer','between:1,100'],'direction'=>['nullable',Rule::in(['asc','desc'])]]);$q=$this->query($r,$resource);$rows=(clone$q)->leftJoin('users as owners','owners.id','=',$c['table'].'.owner_id')->select($c['table'].'.*','owners.name as owner_name')->orderBy($c['table'].'.created_at',$r->input('direction','desc'))->paginate($r->integer('per_page',20));return response()->json(['data'=>['records'=>$rows,'summary'=>$this->summary($resource,$q)]]);}
public function show(Request$r,string$resource,string$id):JsonResponse{$this->permit($r,$resource,'view');$row=$this->find($resource,$id);abort_unless($row,404);$extra=['activity'=>DB::table('activity_log')->where('subject_id',$row->id)->where('description','like',"marketing_{$resource}.%")->latest()->get()];if($resource==='budgets')$extra['transactions']=DB::table('marketing_budget_transactions')->where('budget_id',$row->id)->latest()->get();if($resource==='reports-audit')$extra['runs']=DB::table('marketing_report_runs')->where('report_id',$row->id)->latest()->get();return response()->json(['data'=>['record'=>$row]+$extra]);}
public function store(Request$r,string$resource):JsonResponse{$this->permit($r,$resource,'create');return$this->save($r,$resource);}
public function update(Request$r,string$resource,string$id):JsonResponse{$this->permit($r,$resource,'update');$row=$this->find($resource,$id);abort_unless($row,404);return$this->save($r,$resource,$row->id);}
public function transition(Request$r,string$resource,string$id):JsonResponse{$this->permit($r,$resource,'update');$row=$this->find($resource,$id);abort_unless($row,404);$d=$r->validate(['action'=>['required',Rule::in(['submit','approve','reject','activate','lock','unlock','close','archive'])]]);if(in_array($d['action'],['approve','reject']))$this->permit($r,$resource,'approve');$u=['updated_by'=>$r->user()->id,'updated_at'=>now()];if(in_array($d['action'],['submit','approve','reject']))$u['approval_status']=['submit'=>'pending','approve'=>'approved','reject'=>'rejected'][$d['action']];elseif(in_array($d['action'],['lock','unlock']))$u['is_locked']=$d['action']==='lock';else$u['status']=$d['action']==='close'?'closed':$d['action'];DB::table(self::R[$resource]['table'])->where('id',$row->id)->update($u);activity('admin')->causedBy($r->user())->withProperties(['resource'=>$resource,'id'=>$row->id,'action'=>$d['action']])->log("marketing_{$resource}.status_changed");return response()->json(['data'=>['record'=>$this->find($resource,(string)$row->id)]]);}
private function save(Request$r,string$resource,?int$id=null):JsonResponse{$c=$this->cfg($resource);$rules=['name'=>[$id?'sometimes':'required','string','max:180'],'type'=>[$id?'sometimes':'required','string','max:60'],'owner_id'=>['nullable','exists:users,id']];if($resource==='budgets')$rules+=['business_unit'=>['nullable','string','max:80'],'brand'=>['nullable','string','max:100'],'period'=>[$id?'sometimes':'required','string','max:40'],'currency'=>['nullable','string','size:3'],'approved_amount'=>['nullable','numeric','min:0'],'forecast_amount'=>['nullable','numeric','min:0'],'controls'=>['nullable','array']];elseif($resource==='governance')$rules+=['severity'=>['nullable',Rule::in(['low','medium','high','critical'])],'scope_type'=>['nullable','string','max:40'],'scope_id'=>['nullable','integer'],'rules'=>['nullable','array'],'effective_on'=>['nullable','date'],'expires_on'=>['nullable','date','after_or_equal:effective_on']];else$rules+=['domain'=>[$id?'sometimes':'required','string','max:60'],'format'=>['nullable',Rule::in(['csv','xlsx','pdf','json'])],'privacy_classification'=>['nullable',Rule::in(['public','internal','confidential','restricted'])],'filters'=>['nullable','array'],'sections'=>['nullable','array'],'schedule_expression'=>['nullable','string','max:120']];$d=$r->validate($rules);foreach(['controls','rules','filters','sections']as$j)if(isset($d[$j]))$d[$j]=json_encode($d[$j]);$creating=$id===null;$d['updated_by']=$r->user()->id;$d['updated_at']=now();if($creating){$d['uuid']=(string)Str::uuid();$d['code']=$c['prefix'].'-'.now()->format('Y').'-'.str_pad((string)((DB::table($c['table'])->max('id')??0)+1),5,'0',STR_PAD_LEFT);$d['created_by']=$r->user()->id;$d['created_at']=now();$id=DB::table($c['table'])->insertGetId($d);}else DB::table($c['table'])->where('id',$id)->update($d);activity('admin')->causedBy($r->user())->withProperties(['resource'=>$resource,'id'=>$id])->log("marketing_{$resource}.".($creating?'created':'updated'));return response()->json(['data'=>['record'=>$this->find($resource,(string)$id)]],$creating?201:200);}
private function attribution(Request$r):JsonResponse{$q=DB::table('marketing_attribution_results as ar')->join('marketing_attribution_runs as run','run.id','=','ar.run_id');if($r->filled('model'))$q->where('run.model',$r->model);if($r->filled('date_from'))$q->whereDate('ar.metric_date','>=',$r->date_from);if($r->filled('date_to'))$q->whereDate('ar.metric_date','<=',$r->date_to);return response()->json(['data'=>['updated_at'=>now()->toIso8601String(),'metrics'=>['revenue'=>(string)(clone$q)->sum('ar.revenue'),'spend'=>(string)(clone$q)->sum('ar.spend'),'conversions'=>(int)(clone$q)->sum('ar.conversion_count')],'performance'=>(clone$q)->selectRaw('metric_date,sum(revenue) revenue,sum(spend) spend,sum(conversion_count) conversions')->groupBy('metric_date')->orderBy('metric_date')->get(),'channels'=>(clone$q)->selectRaw('channel,sum(revenue) revenue,sum(spend) spend,sum(conversion_count) conversions')->groupBy('channel')->get(),'campaigns'=>(clone$q)->where('source_type','campaign')->selectRaw('source_id,sum(revenue) revenue,sum(spend) spend,sum(conversion_count) conversions')->groupBy('source_id')->get(),'runs'=>DB::table('marketing_attribution_runs')->latest()->paginate(20)]]);}
private function query(Request$r,string$resource){$t=$this->cfg($resource)['table'];$q=DB::table($t)->whereNull($t.'.deleted_at');foreach(['status','type','approval_status','business_unit','period','domain','format','privacy_classification','severity']as$f)if($r->filled($f)&&$r->$f!=='All')$q->where($t.'.'.$f,$r->$f);if($r->filled('search')){$s='%'.$r->search.'%';$q->where(fn($x)=>$x->where($t.'.name','like',$s)->orWhere($t.'.code','like',$s));}return$q;}private function summary(string$r,$q):array{$counts=(clone$q)->selectRaw('status,count(*) aggregate')->groupBy('status')->pluck('aggregate','status');$x=['total'=>(clone$q)->count(),'status_counts'=>$counts,'updated_at'=>now()->toIso8601String()];if($r==='budgets')$x['metrics']=['approved'=>(string)(clone$q)->sum('approved_amount'),'allocated'=>(string)(clone$q)->sum('allocated_amount'),'committed'=>(string)(clone$q)->sum('committed_amount'),'spent'=>(string)(clone$q)->sum('actual_spend'),'forecast'=>(string)(clone$q)->sum('forecast_amount')];return$x;}private function find(string$r,string$id){$t=$this->cfg($r)['table'];return DB::table($t)->whereNull('deleted_at')->where(fn($q)=>$q->where('code',$id)->orWhere('uuid',$id)->when(ctype_digit($id),fn($x)=>$x->orWhere('id',(int)$id)))->first();}private function cfg(string$r):array{abort_unless(isset(self::R[$r]),404);return self::R[$r];}private function permit(Request$r,string$resource,string$a):void{$scope=$resource==='reports-audit'?'reports':$resource;abort_unless($r->user()->hasPermission("marketing.{$scope}.{$a}")||$r->user()->hasPermission('admin.dashboard.view'),403);}}
